package octal

import (
	"errors"
)

const maxInt64 = int64(1<<63 - 1)

// ParseOctal converts an octal number, represented as a string, to its
// decimal equivalent using first principles (no library conversion).
//
// Each digit d at position n from the right contributes d * 8^n to the
// result. Invalid input (an empty string or any character other than
// the octal digits 0-7) is treated as octal 0 and an error is returned.
func ParseOctal(input string) (int64, error) {
	if input == "" {
		return 0, errors.New("ParseOctal: invalid input, treating as octal 0")
	}

	var result int64
	for _, r := range input {
		if r < '0' || r > '7' {
			return 0, errors.New("ParseOctal: invalid input, treating as octal 0")
		}
		digit := int64(r - '0')
		// Guard against overflow: result*8 + digit must fit in int64.
		if result > (maxInt64-digit)/8 {
			return 0, errors.New("ParseOctal: value out of range")
		}
		result = result*8 + digit
	}
	return result, nil
}
